<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:8px}h2{text-align:center}table{width:100%;border-collapse:collapse}th,td{border:1px solid;padding:4px}th{background:#ddd}</style></head><body><h2>ANEXO {{ strtoupper($annex) }} · HEDIAL2026</h2><p>Periodo: {{ $month }} · Establecimiento: {{ $configuration->ipress_name??'' }}</p><table><thead><tr>@if($annex==='13a')<th>Paciente</th><th>DNI</th><th>HC</th><th>Primera hemodiálisis</th>@elseif(in_array($annex,['13b','13c']))<th>Paciente</th><th>Fecha</th><th>Establecimiento</th><th>Motivo</th><th>Notas</th>@elseif($annex==='14')<th>Fecha</th><th>Punto</th><th>Temp.</th><th>Conductividad</th><th>Dureza</th><th>Cloro total</th><th>Cloro libre</th><th>pH</th><th>Responsable</th>@elseif($annex==='15')<th>Fecha</th><th>Máquina</th><th>Puesto</th><th>Turno</th><th>Inicio</th><th>Final</th><th>Método</th><th>Responsable</th>@elseif($annex==='16')<th>Paciente</th><th>HC</th><th>Fecha</th><th>Acceso arterial</th><th>Acceso venoso</th><th>Observación</th>@else<th>Paciente</th><th>Fecha</th><th>Infección</th><th>Clasificación</th><th>Serologías vinculadas</th>@endif</tr></thead><tbody>@foreach($data as $x)<tr>@if($annex==='13a')<td>{{ $x->full_name }}</td><td>{{ $x->dni }}</td><td>{{ $x->medical_history_number }}</td><td>{{ $x->first_hd_date }}</td>@elseif(in_array($annex,['13b','13c']))<td>{{ $x->patient->full_name }}</td><td>{{ $x->occurred_at->format('d/m/Y') }}</td><td>{{ $x->facility }}</td><td>{{ $x->reason }}</td><td>{{ $x->notes }}</td>@elseif($annex==='14')<td>{{ $x->measured_at->format('d/m/Y H:i') }}</td><td>{{ $x->sampling_point }}</td><td>{{ $x->temperature }}</td><td>{{ $x->conductivity }}</td><td>{{ $x->hardness }}</td><td>{{ $x->total_chlorine }}</td><td>{{ $x->free_chlorine }}</td><td>{{ $x->ph }}</td><td>{{ $x->responsible?->name }}</td>@elseif($annex==='15')<td>{{ $x->work_date->format('d/m/Y') }}</td><td>{{ $x->machine->code }}</td><td>{{ $x->machine->station }}</td><